mapper.select:
SELECT asset_id, project_id, name, asset_type, role, os_name, os_version
FROM asset
WHERE asset_id = #{assetId}

mapper.update:
UPDATE asset
SET name = #{name}, asset_type = #{assetType}, role = #{role, jdbcType=VARCHAR},
    os_name = #{osName, jdbcType=VARCHAR}, os_version = #{osVersion, jdbcType=VARCHAR}
WHERE asset_id = #{assetId}

mapper.select:
SELECT ip_id FROM asset_ip
WHERE asset_id = #{assetId} AND address = #{address} AND phase = #{phase}
LIMIT 1

mapper.update:
UPDATE asset_ip
SET asset_id = #{assetId}, address = #{address}, ip_type = #{ipType}, phase = #{phase},
    ext_whitelisted = #{extWhitelisted}, note = #{note, jdbcType=VARCHAR}
WHERE ip_id = #{ipId}

UPDATE dns_record
SET domain = #{domain}, record_type = #{recordType}, value = #{value},
    ttl = #{ttl}, phase = #{phase}
WHERE dns_id = #{dnsId}

UPDATE certificate
SET domain = #{domain}, issuer = #{issuer, jdbcType=VARCHAR},
    not_after = #{notAfter, jdbcType=DATE}, phase = #{phase}
WHERE cert_id = #{certId}

mapper.select:
SELECT software_id FROM asset_software
WHERE asset_id = #{assetId} AND product = #{product} AND phase = #{phase}
LIMIT 1

mapper.update:
UPDATE asset_software
SET asset_id = #{assetId}, product = #{product}, role = #{role, jdbcType=VARCHAR},
    version = #{version}, release_line = #{releaseLine}, phase = #{phase}
WHERE software_id = #{softwareId}

UPDATE backup_plan
SET asset_id = #{assetId}, last_backup_at = #{lastBackupAt, jdbcType=DATE},
    restore_tested = #{restoreTested}, offsite = #{offsite}, phase = #{phase}
WHERE backup_id = #{backupId}
